export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed);
  const g = Number(inputs.gravity);
  const m = Number(inputs.mass);

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const tTotal = 2 * apexTime;

  const t = Math.min(Math.max(0, time), tTotal);

  const height = u * t - 0.5 * g * t * t;
  const velocity = u - g * t;
  const acceleration = -g;
  const force = m * g;

  let motionState = "At the top";
  if (t === 0) {
    motionState = "Ready to toss";
  } else if (Math.abs(t - apexTime) < 0.015) {
    motionState = "At the top";
  } else if (t < apexTime) {
    motionState = "Rising";
  } else if (t >= tTotal - 0.005) {
    motionState = "Back at launch height";
  } else {
    motionState = "Falling";
  }

  const laneWidth = 270;
  const laneHeight = 350;
  const yTop = 50;

  const leftLane = sdk.panel({
    id: "lane.motion",
    x: 20,
    y: yTop,
    w: laneWidth,
    h: laneHeight,
    title: "The motion",
    state: motionState
  });

  const rightLane = sdk.panel({
    id: "lane.vt",
    x: 310,
    y: yTop,
    w: laneWidth,
    h: laneHeight,
    title: "Velocity over time",
    state: "v = u - g t"
  });

  const axisX = 75;
  const axisYMin = yTop + 300;
  const axisLength = 240;
  const axisMaxVal = 2.2;

  const motionAxis = sdk.axis("axis.height", {
    x: axisX,
    y: axisYMin,
    length: axisLength,
    orientation: "y",
    min: 0,
    max: axisMaxVal,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const ballPixelY = axisYMin - (height / axisMaxVal) * axisLength;
  const ballPixelX = axisX + 45;

  const ball = sdk.circle("ball.toss", ballPixelX, ballPixelY, 26, { role: "learner" });

  const vScale = 15;
  const vecV = sdk.vector("vec.v", 
    { x: ballPixelX - 18, y: ballPixelY },
    { value: velocity, direction: "up", scale: vScale, label: "v" },
    { role: "observed" }
  );

  const vecA = sdk.vector("vec.a",
    { x: ballPixelX + 18, y: ballPixelY },
    { value: acceleration, direction: "up", scale: 10, label: "a" },
    { role: "warning" }
  );

  const calloutLines = [
    "v = " + sdk.format(velocity, 2) + " m/s",
    "a = " + sdk.format(acceleration, 1) + " m/s²",
    "Fg = " + sdk.format(force, 1) + " N"
  ];
  const callout = sdk.callout(ballPixelX + 32, ballPixelY - 30, calloutLines, {
    id: "callout.toss",
    role: "neutral"
  });

  const points = [];
  const stepCount = 20;
  for (let i = 0; i <= stepCount; i++) {
    const pT = (tTotal * i) / stepCount;
    const pV = u - g * pT;
    points.push({ x: pT, y: pV });
  }

  const plotVt = sdk.plot("plot.vt", {
    x: 320,
    y: yTop + 40,
    w: 240,
    h: 260,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: points
      }
    ]
  });

  const objects = [
    ...leftLane,
    ...rightLane,
    motionAxis,
    ball,
    ...vecV,
    ...vecA,
    ...callout,
    plotVt
  ];

  return {
    frame: {
      width: 640,
      height: 420,
      objects: objects,
      readouts: [
        { id: "velocity", value: velocity },
        { id: "acceleration", value: acceleration },
        { id: "force", value: force },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: apexTime,
      apexHeight: apexHeight,
      height: height,
      velocity: velocity,
      acceleration: acceleration,
      force: force
    }
  };
}
